import {fs} from './gta-email-recovery-runtime.mjs';
import {parseEnv} from 'node:util';
import {randomUUID} from 'node:crypto';
const {db}=await import('./reply-runtime-20261007.mjs');
const dir='artifacts/gta-subcontractor-recruiting-20261014/';
const file=dir+'jesse-hiwa-details.json';
if(fs.existsSync(file))throw Error('Prior reservation exists; reconcile before any resend');
const from='+14374650584',to='+16479604564';
const [c]=await db('subcontractors',{phone:'eq.'+to});
if(!c||c.contact_name!=='Jesse'||c.status==='blocked')throw Error('Identity or opt-out conflict');
const recent=await db('sms_messages',{from_number:'eq.'+to,direction:'eq.inbound',order:'created_at.desc',limit:'100'});
if(recent.some(r=>/^(stop|unsubscribe|do not contact)\b/i.test(r.body.trim())))throw Error('Opted out');
const body="Hi Jesse, John from Saturn Star Movers here. Following our call, here are the details for Hiwa's job tomorrow, Thursday October 15:\n\nPickup: 9:00 am at 60 Travail Road, Markham.\nDelivery: 391 Victoria Avenue North, Hamilton.\nRequired: 1 driver with 1 x 26-ft truck.\n\nAs agreed: $150 one-time for the truck, plus $50/hour for the driver.\n\nPlease confirm these details and send the driver's name, phone number and truck licence plate as soon as possible. These are needed for warehouse pickup clearance. Thanks, Jesse.";
const plan={from,to,body,contractor_id:c.id,lead_id:'lead_oaqphq32o',state:'reserved_no_retry',at:new Date().toISOString()};
fs.writeFileSync(file,JSON.stringify(plan,null,2),{flag:'wx'});
const key=parseEnv(fs.readFileSync('.env.local','utf8')).TELNYX_API_KEY;
const response=await fetch('https://api.telnyx.com/v2/messages',{method:'POST',headers:{Authorization:'Bearer '+key,'Content-Type':'application/json'},body:JSON.stringify({from,to,text:body,webhook_url:'https://go.quote2move.com/api/sales/telnyx/messaging',use_profile_webhooks:true}),signal:AbortSignal.timeout(25000)});
const result=await response.json();fs.writeFileSync(file,JSON.stringify({...plan,state:response.ok?'provider_accepted':'provider_rejected',result},null,2));
if(!response.ok||!result.data?.id)throw Error('Not confirmed; reconcile without retry');
const sid='telnyx:'+result.data.id;
const [sms]=await db('sms_messages',{},'POST',{id:randomUUID(),from_number:from,to_number:to,body,direction:'outbound',lead_id:null,twilio_sid:sid,created_at:new Date().toISOString()});
const log=await db('sms_messages',{twilio_sid:'eq.'+sid,select:'id'});if(log.length!==1)throw Error('Receipt mismatch');
const note="Owner-confirmed October 14: Hiwa job October 15 at 09:00; 60 Travail Road Markham to 391 Victoria Avenue North Hamilton; 1 driver and 1 x 26ft truck; agreed $150 one-time truck fee plus $50/hour driver. Details sent to Jesse; driver name, phone, plate and written acknowledgement requested. Insurance/dispatch checks not marked complete.";
await db('subcontractors',{id:'eq.'+c.id},'PATCH',{notes:(c.notes||'')+'\n'+note,updated_at:new Date().toISOString()});
const taskId='hiwa-jesse-dispatch-20261014';
const existing=await db('crm_tasks',{id:'eq.'+taskId});
if(!existing.length)await db('crm_tasks',{},'POST',{id:taskId,title:'Hiwa / Jesse: confirm driver details and correct dispatch scope',description:note+'\nExisting CRM crew note says 2 movers / 15ft, which conflicts with John’s confirmed 1 driver / 26ft. Operations must reconcile the crew packet and obtain warehouse clearance. Agreed amounts are subcontractor costs, not the customer quote. SMS receipt: '+sid,status:'open',priority:'high',category:'operations',owner_name:'Ommy Eshiet',owner_user_id:'4e82b448-188d-45b0-96dc-340ee7d4ca2e',related_type:'lead',related_id:'lead_oaqphq32o',related_label:'Hiwa',source:'manual',source_key:taskId,created_by_name:'John via Codex'});
fs.writeFileSync(file,JSON.stringify({...plan,state:'accepted_crm_verified',result,sms_id:sms.id,task_id:taskId},null,2));
console.log(JSON.stringify({recipient:'Jesse',state:'accepted_crm_verified',sid,task_id:taskId}));
